const request = $json;
const headers = request.headers ?? {};
const body = request.body ?? request;
const configuredSecret = String($env.ROUTINES_WEBHOOK_SECRET || '');
const headerSecret = String(headers['x-routines-secret'] || headers['X-Routines-Secret'] || '');
const authorization = String(headers.authorization || headers.Authorization || '');
const bearerSecret = authorization.toLowerCase().startsWith('bearer ') ? authorization.slice(7).trim() : '';

if (!configuredSecret) {
  return [{ json: { ok: false, statusCode: 503, error: 'ROUTINES_WEBHOOK_SECRET não configurado no n8n.' } }];
}

if (headerSecret !== configuredSecret && bearerSecret !== configuredSecret) {
  return [{ json: { ok: false, statusCode: 401, error: 'Não autorizado.' } }];
}

const message = typeof body.message === 'string' ? body.message.trim() : '';
const rawConditions = Array.isArray(body.conditions) ? body.conditions : [];

if (!message || message.length > 20000) {
  return [{ json: { ok: false, statusCode: 400, error: 'message deve conter entre 1 e 20000 caracteres.' } }];
}

if (rawConditions.length < 1 || rawConditions.length > 100) {
  return [{ json: { ok: false, statusCode: 400, error: 'conditions deve conter entre 1 e 100 itens.' } }];
}

const seen = new Set();
const conditions = [];
for (const item of rawConditions) {
  const id = typeof item?.id === 'string' ? item.id.trim() : '';
  const intent = typeof item?.intent === 'string' ? item.intent.trim() : '';
  if (!id || id.length > 100 || !intent || intent.length > 1000 || seen.has(id)) {
    return [{ json: { ok: false, statusCode: 400, error: 'Cada condição precisa de id único e intent válido.' } }];
  }
  seen.add(id);
  conditions.push({ id, intent });
}

return [{ json: { ok: true, statusCode: 200, message, conditions } }];

