          matches: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                conditionId: { type: 'string' },
                matched: { type: 'boolean' }
              },
              required: ['conditionId', 'matched']
            }
          }
        },
        required: ['matches']
      }
    }
  }
} }}

