const request = $('Validar Requisição').first().json;
const knownIds = new Set(request.conditions.map((condition) => condition.id));
const matches = Object.fromEntries(request.conditions.map((condition) => [condition.id, false]));

let outputText = typeof $json.output_text === 'string' ? $json.output_text : '';
if (!outputText && Array.isArray($json.output)) {
  for (const item of $json.output) {
    if (!Array.isArray(item?.content)) continue;
    const content = item.content.find((entry) => entry?.type === 'output_text' && typeof entry.text === 'string');
    if (content?.text) { outputText = content.text; break; }
  }
}

if (!outputText) throw new Error('A OpenAI não retornou output_text.');
const parsed = JSON.parse(outputText);
const results = Array.isArray(parsed?.matches) ? parsed.matches : [];

for (const result of results) {
  const conditionId = typeof result?.conditionId === 'string' ? result.conditionId : '';
  if (knownIds.has(conditionId)) matches[conditionId] = result.matched === true;
}

return [{ json: { matches } }];
